**area(shape)**

Finish `area` for every `Shape`, switching on `kind`, and add a `default` branch that assigns `shape` to a `never` variable so a new shape can't be forgotten.

```ts
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number }
  | { kind: "rect"; width: number; height: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    // TODO: square, rect, and a never check
  }
}
```

notes.back:
// Why: Inside `case "rect"`, TypeScript knows shape has width and height. In default every
// variant has been handled, so shape is `never`; add a variant without a case and that
// assignment stops compiling.
// Docs: https://www.typescriptlang.org/docs/handbook/2/narrowing.html
type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number }
  | { kind: "rect"; width: number; height: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "square":
      return shape.side ** 2;
    case "rect":
      return shape.width * shape.height;
    default: {
      const unreachable: never = shape;
      throw new Error(`unknown shape: ${JSON.stringify(unreachable)}`);
    }
  }
}

