**Type the counter's actions**

`Action` is too loose: the compiler accepts `{ type: "add" }` with no amount, and actions that don't exist. Replace it with a discriminated union of the three real actions.

```ts
type Action = { type: string; amount?: number };

function counter(state: number, action: Action): number {
  switch (action.type) {
    case "increment":
      return state + 1;
    case "add":
      return state + (action.amount ?? 0);
    case "reset":
      return 0;
    default:
      return state;
  }
}
```

notes.back:
// Why: With one object type per action, "add" must carry an amount and unknown types are
// rejected where the action is created — and the switch needs no default.
// Docs: https://www.typescriptlang.org/docs/handbook/2/narrowing.html
type Action =
  | { type: "increment" }
  | { type: "add"; amount: number }
  | { type: "reset" };

function counter(state: number, action: Action): number {
  switch (action.type) {
    case "increment":
      return state + 1;
    case "add":
      return state + action.amount;
    case "reset":
      return 0;
  }
}

